    mr0, mr1 = min(r for r, c in marker), max(r for r, c in marker)
    mc0, mc1 = min(c for r, c in marker), max(c for r, c in marker)

    # A cross-shaped marker indicates reflection below the source.
    rows = {}
    for r, c in marker:
        rows.setdefault(r, []).append(c)
