        len(cs) >= 3 and
        any(r0 < r < r1 and r0 in rows and r1 in rows
            for r0 in rows for r1 in rows)
        for r, cs in rows.items()
    )
    if cross_like and mr0 > sr1:
        for r, c in src:
            rr = 2 * sr1 + 1 - r
