 "content": "def transform(grid):
    """Reflect the 4-pattern in the direction indicated by the 6-pattern.

    Demo patterns show a T-shaped marker choosing the reflection axis and
    direction. For the inverted-T marker, the shape is reflected leftward;
    the upright T directs a rightward reflection. Cross-shaped markers direct
    a vertical reflection below the original shape.
    """
    h, w = len(grid), len(grid[0])
    source = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [[0] * w for _ in range(h)]
    for r, c in source:
        out[r][c] = 4
    if not source or not marker:
        return out

    mr0 = min(r for r, c in marker)
    mr1 = max(r for r, c in marker)
    widths = {}
    for r, c in marker:
        widths[r] = widths.get(r, 0) + 1
    top_width = widths[mr0]
    bottom_width = widths[mr1]

    if bottom_width >= 3 and top_width == 1:
        # Inverted T: reflect the source horizontally to its left.
        sc0 = min(c for r, c in source)
        for r, c in source:
            cc = 2 * sc0 - 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    elif top_width >= 3 and bottom_width == 1:
        # Upright T: reflect the source horizontally to its right.
        sc1 = max(c for r, c in source)
        for r, c in source:
            cc = 2 * sc1 + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        # Cross-like marker: reflect the source vertically below it.
        sr1 = max(r for r, c in source)
        for r, c in source:
            rr = 2 * sr1 + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    return out
